const $ = (s, root = document) => root.querySelector(s);
const app = $('#app');
const state = { user: null, courses: [], page: 'home', authRole: 'student', authMode: 'login', authError: '', filter: 'All Courses', search: '', selectedCourse: null, activeTab: 'lessons', activeLesson: null, quiz: null, attempts: [], quizResult: null, posts: [], assignments: [], submissions: [], assignmentSelected: null, gradebook: null, myGrades: [], overview: null, students: [], announcements: [], annFilter: 'all', modal: null, quizDraft: [], mobileOpen: false, busy: false };
const icons = {home:'⌂',courses:'▦',mine:'▣',students:'♧',manage:'▤',analytics:'◫',back:'←',logout:'↪',chevron:'→',book:'▤',check:'✓',play:'▷',discussion:'◉',quiz:'◇'};
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const color = (value) => /^#[0-9a-fA-F]{6}$/.test(value || '') ? value : '#6979dc';
const icon = (course) => { const names = {learning:'📚',data:'📊',research:'✍️'}; const candidate = String(course?.cover || '📘'); return esc(names[candidate] || ([...candidate].length <= 3 ? candidate : '📘')); };
const n = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;
const percent = value => `${Math.round(n(value))}%`;
const fmtDate = value => { if (!value) return 'N/A'; const date = new Date(value); return Number.isNaN(date.getTime()) ? 'N/A' : date.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' }); };
const initials = value => esc(String(value || 'Z').slice(0, 1));
const url = value => { try { const parsed = new URL(String(value), location.origin); return ['http:', 'https:'].includes(parsed.protocol) ? parsed.href : ''; } catch { return ''; } };
const em = (title, body, action = '') => `<div class="empty"><div class="empty-icon">✦</div><h3>${esc(title)}</h3><p>${esc(body)}</p>${action}</div>`;
const showToast = (message, error = false) => { const el = document.createElement('div'); el.className = `toast${error ? ' error' : ''}`; el.textContent = message; $('#toast-area').append(el); setTimeout(() => el.remove(), 4200); };
async function api(path, options = {}) {
  let response;
  try { response = await fetch(path, { credentials: 'same-origin', headers: { 'Content-Type': 'application/json', ...(options.headers || {}) }, ...options }); }
  catch { throw new Error('Unable to connect. Check your connection or refresh the page.'); }
  let data = {}; try { data = await response.json(); } catch {}
  if (!response.ok) {
    if (response.status === 401 && state.user) { state.user = null; state.selectedCourse = null; state.page = 'home'; render(); }
    throw new Error(data.error || `Action failed (${response.status})`);
  }
  return data;
}
async function run(fn, errorPrefix = '') { if (state.busy) return; state.busy = true; try { await fn(); } catch (error) { showToast(`${errorPrefix}${error.message}`, true); } finally { state.busy = false; } }
async function refreshCourses() { const data = await api('/api/courses'); state.courses = Array.isArray(data.courses) ? data.courses : []; }
async function refreshAnnouncements() { try { const data = await api('/api/announcements'); state.announcements = Array.isArray(data.announcements) ? data.announcements : []; } catch { state.announcements = []; } }
async function refreshOverview() { if (state.user?.role !== 'teacher') return; const data = await api('/api/teacher/overview'); state.overview = data; }
async function refreshStudents() { const data = await api('/api/teacher/students'); state.students = Array.isArray(data.students) ? data.students : []; }
async function loadCourse(id, tab = 'lessons') { const data = await api(`/api/courses/${encodeURIComponent(id)}`); state.selectedCourse = data.course; state.page = 'detail'; state.activeTab = tab; state.activeLesson = null; state.quiz = null; state.attempts = []; state.quizResult = null; state.posts = []; await loadTabData(tab); render(); window.scrollTo({top:0,behavior:'smooth'}); }
async function reloadSelected() { if (!state.selectedCourse) return; const data = await api(`/api/courses/${encodeURIComponent(state.selectedCourse.id)}`); state.selectedCourse = data.course; const idx = state.courses.findIndex(c => c.id === data.course.id); if (idx >= 0) state.courses[idx] = data.course; render(); }
async function loadTabData(tab) { if (!state.selectedCourse) return; const id = encodeURIComponent(state.selectedCourse.id); if (state.user.role === 'student' && !state.selectedCourse.enrolled) return; if (tab === 'quiz') { const data = await api(`/api/courses/${id}/quiz`); state.quiz = data.quiz || null; state.attempts = Array.isArray(data.attempts) ? data.attempts : []; } if (tab === 'discussion') { const data = await api(`/api/courses/${id}/discussions`); state.posts = Array.isArray(data.posts) ? data.posts : []; } }
function brand() { return `<div class="brand"><span class="brand-icon">Z</span><span class="brand-text">Zhixing Learning<small>ZHIXING LEARNING</small></span></div>`; }
function authPage() {
  const registering = state.authMode === 'register'; const student = state.authRole === 'student';
  const accountLabel = student ? 'Student Account ID' : 'Instructor Account ID';
  const accountPlaceholder = student ? 'For example 20260101' : 'For example tch202601';
  const accountHint = student ? 'Digits only (length set by your school). Each student ID can be used only once.' : 'Must start with tch followed by digits (e.g. tch202601).';
  return `<div class="auth-layout"><section class="auth-brand-panel">${brand()}<div class="auth-promo"><div class="eyebrow">LEARN · EXPLORE · GROW</div><h1>Make every lesson count.<br>Grow with every step.</h1><p>A digital classroom for university students. Courses, collaboration, and feedback come together in one place.</p><div class="auth-visual"><div class="auth-visual-head"><strong>My learning progress</strong><span>Progress this week ✦</span></div><div class="auth-visual-bar"><span style="width:76%"></span></div><div class="auth-visual-bar"><span style="width:54%;background:#a5e7d3"></span></div><div class="auth-visual-avatars"><span>A</span><span>B</span><span>C</span><em>Explore new ideas with classmates</em></div></div></div><footer>© ${new Date().getFullYear()} Zhixing Learning · Designed for better learning</footer></section><section class="auth-form-panel"><div class="auth-topnav"><span>${registering ? 'Already registered?' : 'New to Zhixing?'}</span><button type="button" data-action="auth-mode" data-mode="${registering ? 'login' : 'register'}">${registering ? 'Back to Sign In' : 'Create Account →'}</button></div><div class="auth-form-wrap"><div class="eyebrow">WELCOME TO ZHIXING</div><h2>${registering ? student ? 'Start Your Learning Journey' : 'Create Your Teaching Workspace' : 'Welcome Back 👋'}</h2><p class="intro">${registering ? student ? 'Choose Student, Instructor, or Administrator to register your account.' : 'Create an instructor account, then create courses and share enrollment codes with students.' : 'Sign in with your account ID or email to open your workspace.'}</p>${registering ? `<div class="field"><label for="auth-role-select">Account Role</label><select id="auth-role-select" name="role" aria-label="Choose Your Role"><option value="student"${student ? ' selected' : ''}>👨‍🎓 Student</option><option value="teacher"${!student ? ' selected' : ''}>👩‍🏫 Instructor</option></select></div>` : ''}${state.authError ? `<div class="form-error">${esc(state.authError)}</div>` : ''}<form id="auth-form">${registering ? `<div class="field"><label for="auth-name">Name</label><input id="auth-name" name="name" autocomplete="name" placeholder="Enter your full name" required></div><div class="field"><label for="auth-accountId">${accountLabel}</label><input id="auth-accountId" name="accountId" autocomplete="off" placeholder="${accountPlaceholder}" required><div class="field-hint">${accountHint}</div></div><div class="field"><label for="auth-email">Email Address</label><input id="auth-email" type="email" name="email" autocomplete="email" placeholder="you@example.com" required></div>` : `<div class="field"><label for="auth-identifier">Account ID or Email</label><input id="auth-identifier" name="identifier" autocomplete="username" placeholder="e.g. 20260101, tch202601, SIU199901, or you@example.com" required><div class="field-hint">Students use digits, instructors use tch…, administrators start with a letter (e.g. SIU199901), or enter your email.</div></div>`}<div class="field"><label for="auth-password">Password</label><input id="auth-password" type="password" name="password" autocomplete="${registering ? 'new-password' : 'current-password'}" placeholder="${registering ? 'At least 8 characters' : 'Enter your password'}" minlength="8" required></div><button class="btn btn-primary auth-submit" type="submit">${registering ? `Create ${student ? 'Student' : 'Instructor'} Account →` : 'Sign In →'}</button></form><p class="auth-bottom">${registering ? 'Already have an account?' : 'Need an account?'} <button type="button" data-action="auth-mode" data-mode="${registering ? 'login' : 'register'}">${registering ? 'Sign In' : 'Register Account'}</button></p></div></section></div>`;
}
function navItem(page, label, glyph, count = '') { return `<button type="button" data-action="navigate" data-page="${page}" class="nav-btn ${state.page === page || (state.page === 'detail' && page === 'courses') ? 'active' : ''}"><span class="ico">${glyph}</span>${label}${count ? `<span class="nav-count">${count}</span>` : ''}</button>`; }
function shell(content) { const teacher = state.user?.role === 'teacher'; const enrolled = state.courses.filter(c => c.enrolled).length; const nav = teacher ? `${navItem('home','Dashboard',icons.home)}${navItem('manage','Course Management',icons.manage)}${navItem('students','Student Monitoring',icons.students)}${navItem('courses','My Courses',icons.courses)}` : `${navItem('home','Learning Overview',icons.home)}${navItem('courses','Browse Courses',icons.courses)}${navItem('mine','My Learning',icons.mine,enrolled || '')}`; const title = {home:teacher?'Instructor Dashboard':'Learning Overview',courses:teacher?'My Courses':'Browse Courses',mine:'My Learning',manage:'Course Management',students:'Student Monitoring',detail:state.selectedCourse?.title || 'Course Details'}[state.page] || 'Learning Space';
  return `<div class="mobile-overlay ${state.mobileOpen ? 'show' : ''}" data-action="close-menu"></div><div class="app-shell"><aside class="sidebar ${state.mobileOpen ? 'open' : ''}">${brand()}<div class="sidebar-label">${teacher ? 'TEACHING SPACE' : 'MY LEARNING'}</div><nav class="nav-list" aria-label="Main Menu">${nav}</nav><div class="sidebar-bottom"><div class="help-card"><strong>${teacher ? 'Teaching with care' : 'Your learning starts now'}</strong><p>${teacher ? 'Keep content current and follow student progress.' : 'Find courses that interest you and track your progress.'}</p><button type="button" data-action="navigate" data-page="${teacher ? 'manage' : 'courses'}">${teacher ? 'Manage Courses' : 'Explore Courses'} →</button></div><div class="side-user"><span class="avatar sm">${initials(state.user?.name)}</span><span class="side-user-text"><strong>${esc(state.user?.name)}</strong><small>${teacher ? 'Instructor' : `Student · ${esc(state.user?.studentId || '')}`}</small></span><button class="icon-btn" type="button" data-action="logout" aria-label="Sign Out" title="Sign Out">${icons.logout}</button></div></div></aside><div class="main-area"><header class="topbar"><div class="row"><button class="mobile-menu" type="button" data-action="toggle-menu" aria-label="Open Menu">☰</button><div class="breadcrumbs">Zhixing Learning / <b>${esc(title)}</b></div></div><div class="topbar-right"><span class="top-date">${new Date().toLocaleDateString('en-US',{month:'long',day:'numeric',weekday:'long'})}</span><span class="role-chip">${teacher ? 'Instructor Space' : 'Student Space'}</span><span class="avatar sm">${initials(state.user?.name)}</span></div></header><main class="content">${content}<footer class="site-footer">Zhixing Learning · Learn without limits</footer></main></div></div>${modal()}`;
}
function stat(label, value, foot, glyph) { return `<article class="stat-card"><div class="stat-icon">${glyph}</div><div class="stat-label">${label}</div><div class="stat-value">${esc(value)}</div><div class="stat-foot">${esc(foot)}</div></article>`; }
function courseCard(course, teacher = false) { const lessonCount = course.lessons?.length || 0; return `<article class="course-card"><div class="course-cover" style="--cover:${color(course.color)}"><span class="cover-icon">${icon(course)}</span><span class="cover-tag">${esc(course.category || 'General Studies')}</span></div><div class="course-body"><div class="course-category">${teacher ? 'Teaching Course' : course.enrolled ? 'In Progress' : 'Available Course'}</div><h3 class="course-title">${esc(course.title)}</h3><p class="course-description">${esc(course.description || 'Start exploring and learning.')}</p><div class="course-meta"><span>▤ ${lessonCount} learning units</span><span>♧ ${n(course.studentCount)} learners</span></div>${!teacher && course.enrolled ? `<div class="progress-label"><span>Learning Progress</span><b>${percent(course.progress)}</b></div><div class="progress-track"><span style="width:${Math.max(0,Math.min(100,n(course.progress)))}%"></span></div>` : ''}<div class="course-footer"><span class="pill ${course.enrolled ? 'green' : 'blue'}">${teacher ? 'Your Course' : course.enrolled ? 'Enrolled' : 'Open for Enrollment'}</span><button class="btn btn-soft btn-sm" type="button" data-action="open-course" data-id="${esc(course.id)}">${teacher ? 'Manage Course' : course.enrolled ? 'Continue Learning' : 'View Course'} →</button></div></div></article>`; }
function courseGrid(courses, teacher = false) { return courses.length ? `<div class="course-grid">${courses.map(c => courseCard(c,teacher)).join('')}</div>` : em('No courses here yet',teacher?'Create your first course to start building your lessons.':'No matching courses. Try another search term.',teacher?`<button class="btn btn-primary" data-action="new-course">+ Create Course</button>`:''); }
const ANN_CAT_LABELS = { school: 'School Info · 学校信息', college: 'College Info · 学院信息', academic: 'Academic Affairs · 教务管理' };
function announcementBoard() {
  const all = state.announcements || [];
  const f = state.annFilter || 'all';
  const items = f === 'all' ? all : all.filter(a => a.category === f);
  const pills = [['all','All'],['school','School Info · 学校信息'],['college','College Info · 学院信息'],['academic','Academic Affairs · 教务管理']]
    .map(([k, label]) => `<button type="button" class="${f===k?'active':''}" data-action="ann-filter" data-value="${k}">${label}</button>`).join('');
  return `<section style="margin:26px 0"><div class="section-head"><div><h2>Information & Announcements (信息管理公告)</h2><p>Official school, college, and academic affairs notices published by the administrator</p></div></div><div class="filter-pills" style="margin-bottom:14px">${pills}</div><div class="panel panel-pad">${items.length ? items.slice(0,8).map(a=>`<div class="activity-row" style="align-items:flex-start"><span class="activity-dot"></span><div style="flex:1"><div class="row-between wrap"><strong>${esc(a.title)}</strong><span class="pill blue">${esc(ANN_CAT_LABELS[a.category] || a.category)}</span></div><p style="margin:6px 0;white-space:pre-wrap">${esc(a.content)}</p><small>${esc(a.authorName || 'Administrator')} · ${fmtDate(a.updatedAt || a.createdAt)}</small></div></div>`).join('') : `<p class="small muted">No announcements in this category yet.</p>`}</div></section>`;
}
function studentCourseAnnouncements() {
  const items = [];
  for (const c of state.courses.filter(x => x.enrolled && Array.isArray(x.announcements))) {
    for (const a of c.announcements) items.push({ ...a, courseId: c.id, courseTitle: c.title });
  }
  items.sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));
  if (!items.length) return '';
  return `<section style="margin:24px 0"><div class="section-head"><div><h2>Course Announcements (选修课程公告)</h2><p>Latest notices from your enrolled courses</p></div></div><div class="panel panel-pad">${items.slice(0,6).map(a=>`<div class="activity-row" style="align-items:flex-start"><span class="activity-dot"></span><div style="flex:1"><div class="row-between wrap"><strong>${esc(a.title)}</strong><button class="btn-text" type="button" data-action="open-course" data-id="${esc(a.courseId)}">${esc(a.courseTitle)} →</button></div><p style="margin:6px 0;white-space:pre-wrap">${esc(a.content)}</p><small>${esc(a.authorName || 'Instructor')} · ${fmtDate(a.createdAt)}</small></div></div>`).join('')}</div></section>`;
}
function studentHome() { const enrolled = state.courses.filter(c => c.enrolled); const completed = enrolled.filter(c => n(c.progress) >= 100).length; const mean = enrolled.length ? Math.round(enrolled.reduce((s,c)=>s+n(c.progress),0)/enrolled.length) : 0; const recommended = state.courses.filter(c => !c.enrolled).slice(0,3); return `<div class="page-head"><div><div class="eyebrow">STUDENT DASHBOARD</div><h1>Hello, ${esc(state.user.name)} 👋</h1><p>Take another step toward your goals today.</p></div><button class="btn btn-light" data-action="navigate" data-page="courses">Explore All Courses →</button></div><section class="hero"><div class="hero-copy"><div class="eyebrow">YOUR LEARNING JOURNEY</div><h2>Turn curiosity into your strength.</h2><p>Explore course materials, test your understanding, and discuss ideas with instructors and classmates.</p><button class="btn btn-white" data-action="navigate" data-page="${enrolled.length?'mine':'courses'}">${enrolled.length?'Continue My Learning':'Start Learning'} →</button></div><div class="hero-art"><div class="orb"></div><div class="hero-book"></div><div class="floating-a">✓</div><div class="floating-b">✦</div></div></section><div class="stats-grid">${stat('Enrolled Courses',enrolled.length,'Your personal course list','▦')}${stat('Completed Courses',completed,'Building your knowledge','✓')}${stat('Average Completion',percent(mean),'Track each step forward','◴')}${stat('Available Courses',state.courses.length,'More courses to explore','✦')}</div><div class="section-head"><div><h2>Continue Learning</h2><p>Return to your active courses</p></div><button class="btn-text" data-action="navigate" data-page="mine">View All →</button></div>${enrolled.length?courseGrid(enrolled.slice(0,3)):em('Your learning journey starts here','Choose a course that interests you. Your progress will appear here.',`<button class="btn btn-primary" data-action="navigate" data-page="courses">Browse Courses →</button>`)}<div class="section-head"><div><h2>Recommended for You</h2><p>Fresh perspectives and new possibilities</p></div></div>${recommended.length?courseGrid(recommended):em('You are enrolled in every available course','Go to My Learning to continue your courses.')}${studentCourseAnnouncements()}${announcementBoard()}`; }
function teacherHome() { const o = state.overview || {}; const s = o.stats || {}; return `<div class="page-head"><div><div class="eyebrow">TEACHER WORKSPACE</div><h1>Hello, ${esc(state.user.name)} 👋</h1><p>Follow student progress and make informed teaching decisions.</p></div><button class="btn btn-primary" data-action="new-course">＋ Create New Course</button></div><section class="hero"><div class="hero-copy"><div class="eyebrow">TEACH WITH INSIGHT</div><h2>Every step forward deserves to be seen.</h2><p>Keep track of course content, participation, and quiz results to make every class more engaging.</p><button class="btn btn-white" data-action="navigate" data-page="students">View Student Progress →</button></div><div class="hero-art"><div class="orb"></div><div class="hero-book"></div><div class="floating-a">✎</div><div class="floating-b">◈</div></div></section><div class="stats-grid">${stat('Total Students',n(s.totalStudents),'EnrolledMy Courses','♧')}${stat('Total Courses',n(s.totalCourses),'Courses I created','▦')}${stat('Course Enrollments',n(s.totalEnrollments),'Enrollments in my courses','◉')}${stat('Average Completion',percent(s.avgCompletion),'Progress in my courses','◴')}</div><div class="teacher-grid"><section><div class="section-head"><div><h2>Course Performance</h2><p>See how students are doing in each course</p></div><button class="btn-text" data-action="navigate" data-page="manage">Manage Courses →</button></div><div class="panel">${(o.courses||[]).length ? (o.courses||[]).map(c=>`<div class="course-manage-row"><span class="course-swatch" style="--cover:${color(state.courses.find(x=>x.id===c.id)?.color)}">${icon(state.courses.find(x=>x.id===c.id))}</span><div class="name"><strong>${esc(c.title)}</strong><span>${n(c.enrollments)}  students · Average progress ${percent(c.avgProgress)}</span></div><span class="meta">Average Quiz Score ${c.avgQuizScore==null?'N/A':percent(c.avgQuizScore)}</span><button class="btn btn-soft btn-sm" data-action="open-course" data-id="${esc(c.id)}">View →</button></div>`).join('') : `<div class="teacher-empty">Course performance will appear here once you create a course.</div>`}</div></section><section><div class="section-head"><div><h2>Teaching Activity</h2><p>Recent learning activity</p></div></div><div class="panel panel-pad">${(o.recentActivity||[]).length ? (o.recentActivity||[]).slice(0,5).map(a=>`<div class="activity-row"><span class="activity-dot"></span><div><p>${esc(activityText(a))}</p><small>${fmtDate(a.createdAt)}</small></div></div>`).join('') : `<p class="small muted">Recent learning activity will appear here once students participate.</p>`}<div class="section-head" style="margin-bottom:5px"><h3 style="font-size:14px;margin:0">Teaching Tips</h3></div><ul class="note-list"><li>Update course materials regularly</li><li>Use quiz results to guide teaching</li><li>Respond to students in discussions</li></ul></div></section></div>${announcementBoard()}`; }
function catalog(mine = false) { const teacher = state.user?.role === 'teacher'; let courses = state.courses.filter(c => teacher ? c.teacherId === state.user.id : !mine || c.enrolled); const categories = ['All Courses',...new Set(courses.map(c=>c.category).filter(Boolean))]; const filter = categories.includes(state.filter) ? state.filter : 'All Courses'; if (filter !== 'All Courses') courses = courses.filter(c=>c.category === filter); if (state.search) courses = courses.filter(c=>`${c.title} ${c.description} ${c.category}`.toLowerCase().includes(state.search.toLowerCase())); return `<div class="page-head"><div><div class="eyebrow">${teacher ? 'COURSE LIBRARY' : mine ? 'MY LEARNING' : 'EXPLORE COURSES'}</div><h1>${teacher ? 'My Courses' : mine ? 'My Learning' : 'Browse Courses'}</h1><p>${teacher ? 'Browse and manage the courses you created.' : mine ? 'Keep track of your progress and continue learning.' : 'Explore new subjects and discover what to learn next.'}</p></div>${teacher ? `<button class="btn btn-primary" data-action="new-course">＋ Create Course</button>` : ''}</div><div class="filter-line"><div class="filter-pills">${categories.map(c=>`<button class="${filter===c?'active':''}" data-action="filter" data-value="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="searchbar"><span>⌕</span><input id="course-search" type="search" value="${esc(state.search)}" placeholder="Search courses or keywords" aria-label="Search Courses"></div></div>${courseGrid(courses,teacher)}`; }
function teacherManage() { const courses = state.courses.filter(c => c.teacherId === state.user.id); return `<div class="page-head"><div><div class="eyebrow">COURSE MANAGEMENT</div><h1>Course Management</h1><p>Create, update, or remove courses and lessons.</p></div><button class="btn btn-primary" data-action="new-course">＋ Create New Course</button></div><div class="section-head"><div><h2>My Courses <span class="pill blue">${courses.length}</span></h2><p>Select Manage to add lessons, quizzes, and discussions</p></div></div><div class="panel">${courses.length ? courses.map(c=>`<div class="course-manage-row"><span class="course-swatch" style="--cover:${color(c.color)}">${icon(c)}</span><div class="name"><strong>${esc(c.title)}</strong><span>${esc(c.category||'General Studies')} · ${c.lessons?.length||0} learning units · ${n(c.studentCount)} students</span></div><span class="meta">${c.quizAvailable?'Quiz Ready':'No Quiz Yet'}</span><button class="btn btn-light btn-sm" data-action="edit-course" data-id="${esc(c.id)}">Edit</button><button class="btn btn-soft btn-sm" data-action="open-course" data-id="${esc(c.id)}">Manage →</button></div>`).join('') : `<div class="teacher-empty">No courses yet. Select Create Course to get started.</div>`}</div>`; }
function studentsPage() { return `<div class="page-head"><div><div class="eyebrow">STUDENT MONITORING</div><h1>Student Progress Monitoring</h1><p>Review student enrollment, progress, and quiz results.</p></div><span class="pill blue">Total  ${state.students.length} students</span></div>${state.students.length ? `<div class="panel table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>Student ID</th><th>My Courses</th><th>Average Progress</th><th>Recent Activity</th><th></th></tr></thead><tbody>${state.students.map(s=>`<tr><td><span class="student-name"><span class="avatar">${initials(s.name)}</span><span><strong>${esc(s.name)}</strong><small>${esc(s.email)}</small></span></span></td><td>${esc(s.studentId)}</td><td>${s.enrollments?.length||0} courses</td><td><div class="bar-cell"><div class="progress-track"><span style="width:${Math.max(0,Math.min(100,n(s.avgProgress)))}%"></span></div><strong>${percent(s.avgProgress)}</strong></div></td><td>${fmtDate(s.lastActiveAt)}</td><td><button class="btn btn-soft btn-sm" data-action="student-detail" data-id="${esc(s.id)}">View Details →</button></td></tr>`).join('')}</tbody></table></div>` : em('No student data yet','Once students enroll, you can track their progress here.')}`; }
function lessonsPanel(course) { const teacher = state.user.role === 'teacher'; const completed = new Set(course.completedLessonIds || []); const lessons = [...(course.lessons || [])].sort((a,b)=>n(a.order)-n(b.order)); return `<div class="row-between" style="margin-bottom:10px"><div><h3 style="margin:0">Course Outline</h3><p class="tiny muted" style="margin:4px 0 0">${lessons.length} learning units · Learn at your own pace</p></div>${teacher ? `<button class="btn btn-soft btn-sm" data-action="new-lesson">＋ Add Lesson</button>` : ''}</div>${lessons.length ? lessons.map((lesson,i)=>`<div class="lesson-row"><span class="lesson-icon ${completed.has(lesson.id)?'done':''}">${completed.has(lesson.id) ? '✓' : lesson.type==='video'?'▷':'▤'}</span><span class="lesson-info"><b>${String(i+1).padStart(2,'0')}. ${esc(lesson.title)}</b><small>${lesson.type==='video'?'Video Lesson':lesson.type==='assignment'?'Assignment':'Reading Lesson'} · ${esc(lesson.duration || 'Self-Paced Learning')}${completed.has(lesson.id) ? ' · Completed' : ''}</small></span>${teacher ? `<button class="btn btn-light btn-sm" data-action="edit-lesson" data-id="${esc(lesson.id)}">Edit</button>` : ''}<button class="btn btn-soft btn-sm" data-action="open-lesson" data-id="${esc(lesson.id)}">${teacher?'Preview':'Start Learning'} →</button></div>`).join('') : em('Lessons coming soon','Lessons will appear when your instructor adds them.',teacher?`<button class="btn btn-primary" data-action="new-lesson">＋ Add the First Lesson</button>`:'')}${state.activeLesson ? lessonView(course,lessons.find(l=>l.id===state.activeLesson)) : ''}`; }
function lessonView(course, lesson) { if (!lesson) return ''; const teacher = state.user.role === 'teacher'; const completed = (course.completedLessonIds||[]).includes(lesson.id); const video = url(lesson.videoUrl); const isNativeVideo = /[.](mp4|webm|ogg)([?#]|$)/i.test(video); return `<section class="lesson-open"><div class="row-between"><h3>${esc(lesson.title)}</h3><button class="icon-btn" data-action="close-lesson" aria-label="Close Lesson">✕</button></div>${lesson.content ? `<div class="lesson-content">${esc(lesson.content)}</div>` : `<p class="small muted">No written content yet.</p>`}${video ? (isNativeVideo ? `<video class="lesson-video" controls preload="metadata" src="${esc(video)}">Your browser cannot play this video.</video>` : `<p><a class="btn btn-light btn-sm" href="${esc(video)}" target="_blank" rel="noopener noreferrer">Open Video in a New Tab ↗</a></p>`) : ''}${teacher ? `<div class="row"><button class="btn btn-light btn-sm" data-action="edit-lesson" data-id="${esc(lesson.id)}">Edit Lesson</button><button class="btn btn-danger btn-sm" data-action="delete-lesson" data-id="${esc(lesson.id)}">Delete Lesson</button></div>` : course.enrolled ? `<button class="btn ${completed?'btn-light':'btn-primary'}" data-action="complete-lesson" data-id="${esc(lesson.id)}" ${completed?'disabled':''}>${completed?'✓ Completed':'✓ Mark as Complete'}</button>` : `<p class="small muted">Enroll to track your learning progress.</p>`}</section>`; }
function quizPanel(course) { const teacher = state.user.role === 'teacher'; const questions = state.quiz?.questions || []; const attempts = state.attempts || []; if (teacher) return `<div class="row-between" style="margin-bottom:16px"><div><h3 style="margin:0">Course Quiz</h3><p class="tiny muted" style="margin:5px 0 0">Create multiple-choice questions with automatic grading</p></div><button class="btn btn-soft btn-sm" data-action="edit-quiz">${questions.length?'Edit Quiz':'＋ Create Quiz'}</button></div>${questions.length ? `<div class="quiz-intro"><strong>${questions.length} multiple-choice questions</strong><p>Quiz results are automatically recorded in your instructor dashboard.</p></div>${questions.map((q,i)=>`<div class="question-card"><div class="question-top"><span class="question-number">${i+1}</span><b>${esc(q.text)}</b></div><div class="small muted">${(q.options||[]).map((o,k)=>`${String.fromCharCode(65+k)}. ${esc(o)}`).join('  ' )}</div></div>`).join('')}` : em('No course quiz yet','Create quiz questions to understand what students have learned.',`<button class="btn btn-primary" data-action="edit-quiz">Create Quiz →</button>`)}<p class="small muted">The answer key is not shown to students.</p>`; if (!course.enrolled) return em('Enroll to take this quiz','Take a quiz after class to check your understanding.',`<button class="btn btn-primary" data-action="enroll">Enroll in Course →</button>`); if (!questions.length) return em('Quiz coming soon','Questions will appear when your instructor publishes a quiz.'); return `<div class="quiz-intro"><strong>Course Knowledge Check · ${questions.length} questions</strong><p>Choose one answer per question and get instant feedback after submitting.</p></div>${state.quizResult ? `<div class="score-result"><strong>${percent(state.quizResult.percent)}</strong><span>Correct answers:  ${n(state.quizResult.score)} / ${n(state.quizResult.total)} question</span><br><small>Your score has been recorded. Keep going!</small></div>` : ''}<form id="quiz-form">${questions.map((q,i)=>`<div class="question-card"><div class="question-top"><span class="question-number">${i+1}</span><b>${esc(q.text)}</b></div>${(q.options||[]).map((option,k)=>`<label class="option"><input type="radio" name="q-${esc(q.id)}" value="${k}"><span>${String.fromCharCode(65+k)}. ${esc(option)}</span></label>`).join('')}</div>`).join('')}<button class="btn btn-primary" type="submit">Submit Answers and View Results →</button></form>${attempts.length ? `<div class="section-head"><h3>Quiz History</h3></div><div class="panel panel-pad">${attempts.slice().reverse().slice(0,6).map(a=>`<div class="mini-stat"><span>${fmtDate(a.submittedAt)}</span><b>${n(a.score)} / ${n(a.total)} · ${percent(a.percent)}</b></div>`).join('')}</div>` : ''}`; }
function discussionPanel(course) { const teacher = state.user.role === 'teacher'; return `<div class="row-between" style="margin-bottom:18px"><div><h3 style="margin:0">Course Discussion</h3><p class="tiny muted" style="margin:5px 0 0">Ask questions and share ideas with the class</p></div><span class="pill blue">${state.posts.length} posts</span></div>${state.posts.length ? state.posts.map(p=>`<div class="discussion-post"><div class="post-head"><span class="avatar sm">${initials(p.authorName)}</span><strong>${esc(p.authorName)}${p.authorRole==='teacher'?`<span class="bubble">Instructor</span>`:''}</strong><time>${fmtDate(p.createdAt)}</time>${teacher || p.authorId===state.user.id ? `<button class="icon-btn" data-action="delete-post" data-id="${esc(p.id)}" title="Delete this post">✕</button>` : ''}</div><p>${esc(p.content)}</p></div>`).join('') : em('Start the first discussion','Share your questions and discoveries with the class.')}${teacher || course.enrolled ? `<form id="discussion-form" class="discussion-form"><label for="post-content">Post a Discussion</label><textarea id="post-content" name="content" maxlength="2000" placeholder="Write your question, idea, or reflection…" required></textarea><div class="row-between" style="margin-top:10px"><span class="tiny muted">Please be kind and respectful</span><button class="btn btn-primary btn-sm" type="submit">Post Discussion →</button></div></form>` : `<p class="small muted" style="margin-top:20px">Enroll to join the discussion.</p>`}`; }
function courseAnnouncementsPanel(course) {
  const teacher = state.user.role === 'teacher';
  if (!teacher && !course.enrolled) return em('Enroll to view course announcements', 'Course announcements are available to enrolled students.', `<button class="btn btn-primary" data-action="enroll">Enroll in Course →</button>`);
  const list = course.announcements || [];
  const formHtml = teacher ? `<form id="course-announcement-form" class="discussion-form" style="margin-top:0;margin-bottom:20px"><label for="course-ann-title">Publish Course Announcement</label><div class="field"><input id="course-ann-title" name="title" maxlength="120" placeholder="Announcement title" required></div><div class="field"><textarea id="course-ann-content" name="content" rows="3" maxlength="5000" placeholder="Write a notice for enrolled students…" required></textarea></div><button class="btn btn-primary btn-sm" type="submit">Publish Course Announcement →</button></form>` : '';
  const itemsHtml = list.length ? list.map(a => `<div class="discussion-post"><div class="post-head"><span class="avatar sm">${initials(a.authorName)}</span><strong>${esc(a.authorName || 'Instructor')}<span class="bubble">Course Notice</span></strong><time>${fmtDate(a.createdAt)}</time>${teacher ? `<button class="icon-btn" data-action="delete-course-ann" data-id="${esc(a.id)}" title="Delete announcement">✕</button>` : ''}</div><h4 style="margin:8px 0 4px">${esc(a.title)}</h4><p style="white-space:pre-wrap">${esc(a.content)}</p></div>`).join('') : em('No course announcements yet', teacher ? 'Publish an announcement above to notify enrolled students.' : 'Your instructor has not posted any course announcements yet.');
  return `<div class="row-between" style="margin-bottom:14px"><div><h3 style="margin:0">Course Announcements</h3><p class="tiny muted" style="margin:4px 0 0">Notices synced to all enrolled students</p></div><span class="pill blue">${list.length} notices</span></div>${formHtml}${itemsHtml}`;
}
function detailPage() { const c = state.selectedCourse; if (!c) return em('Course not found','Return to the course list and try again.'); const teacher = state.user.role === 'teacher'; const lessons = c.lessons?.length||0; return `<div class="row-between" style="margin-bottom:17px"><button class="btn-text" data-action="navigate" data-page="${teacher?'manage':'courses'}">← Back to ${teacher?'Course Management':'Course List'}</button>${teacher ? `<div class="row"><button class="btn btn-light btn-sm" data-action="edit-course" data-id="${esc(c.id)}">Edit Course</button><button class="btn btn-danger btn-sm" data-action="delete-course" data-id="${esc(c.id)}">Delete Course</button></div>` : ''}</div><div class="detail-hero"><div class="detail-main"><span class="pill blue">${esc(c.category||'General Studies')}</span><h1>${esc(c.title)}</h1><p>${esc(c.description||'A worthwhile learning journey awaits.')}</p><div class="detail-info"><span>▤ ${lessons} learning units</span><span>♧ ${n(c.studentCount)} learners</span><span>◈ ${c.quizAvailable?'Quiz Ready':'No Quiz Yet'}</span></div></div><div class="detail-aside"><span class="cover-icon">${icon(c)}</span><h3>${teacher?'Teaching Overview':c.enrolled?'Continue Learning':'Ready to get started?'}</h3><p>${teacher?'Add lessons and quizzes to track student performance.':c.enrolled?'Track your progress as you learn.':'Enroll to start learning and participating.'}</p><div class="row-between tiny"><span>${teacher?'Course progress':'Your learning progress'}</span><b>${teacher?`${n(c.studentCount)} students`:percent(c.progress)}</b></div><div class="progress-track"><span style="width:${teacher ? Math.min(100,n(c.studentCount)*12) : Math.max(0,Math.min(100,n(c.progress)))}%"></span></div>${!teacher && !c.enrolled ? `<button class="btn btn-white" data-action="enroll">Enroll in Course →</button>` : ''}</div></div><div class="detail-layout"><section class="panel panel-pad"><div class="tabs"><button class="tab ${state.activeTab==='lessons'?'active':''}" data-action="detail-tab" data-tab="lessons">Course Outline</button><button class="tab ${state.activeTab==='quiz'?'active':''}" data-action="detail-tab" data-tab="quiz">Knowledge Check</button><button class="tab ${state.activeTab==='discussion'?'active':''}" data-action="detail-tab" data-tab="discussion">Discussion</button><button class="tab ${state.activeTab==='announcements'?'active':''}" data-action="detail-tab" data-tab="announcements">Announcements</button></div>${state.activeTab==='quiz'?quizPanel(c):state.activeTab==='discussion'?discussionPanel(c):state.activeTab==='announcements'?courseAnnouncementsPanel(c):lessonsPanel(c)}</section><aside class="panel panel-pad teacher-side"><h3>${teacher?'Course Management Guide':'Study Tips'}</h3><p class="small muted">${teacher?'Update materials regularly, follow discussions, and use quiz results to refine your teaching.':'Review lessons in order, mark them complete, and take a quiz to check your understanding.'}</p><div class="mini-stat"><span>Learning Unit</span><b>${lessons}</b></div><div class="mini-stat"><span>Discussion Posts</span><b>${state.activeTab==='discussion'?state.posts.length:'View Discussion'}</b></div><div class="mini-stat"><span>Knowledge Quiz</span><b>${c.quizAvailable?'Configured':'To Be Added'}</b></div>${teacher ? `<button class="btn btn-soft" style="width:100%;margin-top:22px" data-action="new-lesson">＋ Add New Lesson</button>` : ''}</aside></div>`; }
function modal() { if (!state.modal) return ''; const m = state.modal; if (m.type === 'course') { const c=m.course||{}; return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${c.id?'Edit Course':'Create New Course'}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close">✕</button></div><form id="course-form"><div class="modal-body"><div class="field"><label for="course-title">Course Name *</label><input id="course-title" name="title" value="${esc(c.title)}" placeholder="For example, Introduction to Design Thinking" required maxlength="100"></div><div class="field"><label for="course-description">Course Description *</label><textarea id="course-description" name="description" placeholder="Help students understand the course goals…" required>${esc(c.description)}</textarea></div><div class="form-grid"><div class="field"><label for="course-category">Course Category</label><input id="course-category" name="category" value="${esc(c.category||'Liberal Arts')}" placeholder="For example: Liberal Arts"></div><div class="field"><label for="course-cover">Cover Icon</label><input id="course-cover" name="cover" value="${esc(c.cover||'📘')}" placeholder="📘" maxlength="6"></div></div><div class="field"><label for="course-color">Cover Color</label><input id="course-color" type="color" name="color" value="${color(c.color)}" style="height:48px;padding:5px;cursor:pointer"></div></div><div class="modal-actions"><button class="btn btn-light" type="button" data-action="close-modal">Cancel</button><button class="btn btn-primary" type="submit">${c.id?'Save Changes':'Create Course'}</button></div></form></div></div>`; } if (m.type === 'lesson') { const l=m.lesson||{}; return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${l.id?'Edit Lesson':'Add Learning Unit'}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close">✕</button></div><form id="lesson-form"><div class="modal-body"><div class="field"><label for="lesson-title">Lesson Title *</label><input id="lesson-title" name="title" value="${esc(l.title)}" placeholder="For example, Lesson 1: Core Concepts" required maxlength="120"></div><div class="form-grid"><div class="field"><label for="lesson-type">Content Type</label><select id="lesson-type" name="type"><option value="reading" ${l.type!=='video' && l.type!=='assignment'?'selected':''}>Reading Lesson</option><option value="video" ${l.type==='video'?'selected':''}>Video Lesson</option><option value="assignment" ${l.type==='assignment'?'selected':''}>Assignment</option></select></div><div class="field"><label for="lesson-duration">Estimated Duration</label><input id="lesson-duration" name="duration" value="${esc(l.duration||'15 minutes')}" placeholder="For example: 20 minutes"></div></div><div class="field"><label for="lesson-content">Learning Content</label><textarea id="lesson-content" name="content" rows="7" placeholder="Add notes, learning objectives, questions, and resources…">${esc(l.content)}</textarea></div><div class="field"><label for="lesson-video">Video URL (optional)</label><input id="lesson-video" type="url" name="videoUrl" value="${esc(l.videoUrl)}" placeholder="https://example.com/lesson.mp4"><div class="field-hint">Direct video links are supported; other pages open in a new tab</div></div></div><div class="modal-actions"><button class="btn btn-light" type="button" data-action="close-modal">Cancel</button><button class="btn btn-primary" type="submit">${l.id?'Save Changes':'Add Lesson'}</button></div></form></div></div>`; } if (m.type === 'quiz') return `<div class="modal-backdrop" data-action="close-modal"><div class="modal wide" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">Edit Course Quiz</h2><button class="icon-btn" data-action="close-modal" aria-label="Close">✕</button></div><div class="modal-body"><p class="small muted">Provide four choices and mark the correct answer for each question. Students will not see the answer key.</p><div id="quiz-builder">${state.quizDraft.map((q,i)=>`<div class="question-editor" data-qindex="${i}"><div class="question-editor-header"><strong>Question ${i+1}</strong><button class="btn btn-danger btn-sm" type="button" data-action="remove-question" data-index="${i}">Remove</button></div><div class="field"><label>Question Text *</label><input data-question-field="text" data-index="${i}" value="${esc(q.text)}" placeholder="Enter a question" required></div><div class="option-grid">${[0,1,2,3].map(k=>`<div><label>Option ${String.fromCharCode(65+k)}</label><input data-question-field="option" data-index="${i}" data-option="${k}" value="${esc(q.options?.[k])}" placeholder="Options ${String.fromCharCode(65+k)}" required></div>`).join('')}</div><div class="field"><label>Correct Answer *</label><select data-question-field="correctIndex" data-index="${i}">${[0,1,2,3].map(k=>`<option value="${k}" ${n(q.correctIndex)===k?'selected':''}>Option ${String.fromCharCode(65+k)}</option>`).join('')}</select></div></div>`).join('')}</div><button class="btn btn-light" type="button" data-action="add-question">＋ Add a Question</button></div><div class="modal-actions"><button class="btn btn-light" type="button" data-action="close-modal">Cancel</button><button class="btn btn-primary" type="button" data-action="save-quiz">Save Quiz</button></div></div></div>`; if (m.type === 'student') { const s=m.student; return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${esc(s.name)} - Learning Profile</h2><button class="icon-btn" data-action="close-modal" aria-label="Close">✕</button></div><div class="modal-body"><p class="small muted">Student ID ${esc(s.studentId)} · ${esc(s.email)}</p><div class="student-detail"><div class="mini-stat"><span>Enrolled Courses</span><b>${s.enrollments?.length||0} courses</b></div><div class="mini-stat"><span>Average Completion</span><b>${percent(s.avgProgress)}</b></div><div class="mini-stat"><span>Recent Activity</span><b>${fmtDate(s.lastActiveAt)}</b></div></div><h3 style="margin:22px 0 10px">Enrollment Details</h3>${(s.enrollments||[]).length ? (s.enrollments||[]).map(e=>`<div class="student-detail-row"><div><strong>${esc(e.courseTitle)}</strong><div class="tiny muted">${n(e.completedLessons)} / ${n(e.totalLessons)}  lessons complete · Best quiz score ${e.bestQuizScore==null?'N/A':percent(e.bestQuizScore)}</div></div><span class="pill blue">${percent(e.progress)}</span></div>`).join('') : `<p class="small muted">You have not enrolled in any courses yet.</p>`}</div><div class="modal-actions"><button class="btn btn-light" type="button" data-action="close-modal">Close</button></div></div></div>`; } return ''; }
function render() { if (!state.user) { app.innerHTML = authPage(); return; } let view; if (state.page === 'detail') view = detailPage(); else if (state.page === 'courses') view = catalog(); else if (state.user.role === 'teacher') view = state.page==='manage'?teacherManage():state.page==='students'?studentsPage():teacherHome(); else view = state.page==='mine'?catalog(true):studentHome(); app.innerHTML = shell(view); }
async function navigate(page) { state.mobileOpen=false; state.search=''; state.filter='All Courses'; if (page === 'home' && state.user.role==='teacher') await refreshOverview(); if (page === 'students' && state.user.role==='teacher') await refreshStudents(); if (page === 'mine' && state.user.role==='teacher') page='manage'; if (page === 'manage' && state.user.role!=='teacher') page='courses'; state.page=page; render(); window.scrollTo({top:0,behavior:'smooth'}); }
function openModal(type, item = null) { state.modal = type==='course'?{type,course:item}:type==='lesson'?{type,lesson:item}:type==='student'?{type,student:item}:{type}; if(type==='quiz') { const questions=state.quiz?.questions||[]; state.quizDraft=questions.length ? questions.map(q=>({text:q.text||'',options:[...(q.options||[])].concat(['','','','']).slice(0,4),correctIndex:n(q.correctIndex)})) : [{text:'',options:['','','',''],correctIndex:0}]; } render(); setTimeout(()=>$('.modal input')?.focus(),0); }
function closeModal(){ state.modal=null; render(); }
document.addEventListener('click', async event => { const node=event.target.closest('[data-action]'); if(!node) return; const action=node.dataset.action; const id=node.dataset.id; if(action==='close-modal' && event.target!==node && node.classList.contains('modal-backdrop')) return; event.preventDefault(); if(action==='auth-role'){state.authRole=node.dataset.role;state.authError='';render();return;} if(action==='auth-mode'){state.authMode=node.dataset.mode;state.authError='';render();return;} if(action==='toggle-menu'){state.mobileOpen=!state.mobileOpen;render();return;} if(action==='close-menu'){state.mobileOpen=false;render();return;} if(action==='navigate'){await run(()=>navigate(node.dataset.page));return;} if(action==='logout'){await run(async()=>{await api('/api/auth/logout',{method:'POST'});state.user=null;state.page='home';state.selectedCourse=null;state.authMode='login';state.authError='';render();showToast('You have signed out');});return;} if(action==='open-course'){await run(()=>loadCourse(id),'Could not open course: ');return;} if(action==='filter'){state.filter=node.dataset.value;render();return;} if(action==='ann-filter'){state.annFilter=node.dataset.value;render();return;} if(action==='delete-course-ann'){if(!confirm('Delete this course announcement?'))return;await run(async()=>{await api(`/api/courses/${encodeURIComponent(state.selectedCourse.id)}/announcements/${encodeURIComponent(id)}`,{method:'DELETE'});await reloadSelected();showToast('Course announcement deleted');},'Could not delete: ');return;} if(action==='detail-tab'){await run(async()=>{state.activeTab=node.dataset.tab;state.quizResult=null;await loadTabData(state.activeTab);render();},'Could not load: ');return;} if(action==='open-lesson'){state.activeLesson=id;render();setTimeout(()=>$('.lesson-open')?.scrollIntoView({behavior:'smooth',block:'nearest'}),0);return;} if(action==='close-lesson'){state.activeLesson=null;render();return;} if(action==='enroll'){await run(async()=>{await api(`/api/courses/${encodeURIComponent(state.selectedCourse.id)}/enroll`,{method:'POST'});await refreshCourses();await reloadSelected();showToast('You are enrolled. Start learning!');},'Could not enroll: ');return;} if(action==='complete-lesson'){await run(async()=>{await api(`/api/lessons/${encodeURIComponent(id)}/complete`,{method:'POST'});await refreshCourses();await reloadSelected();showToast('Learning progress saved!');},'Could not save progress: ');return;} if(action==='new-course'){openModal('course');return;} if(action==='edit-course'){openModal('course',state.courses.find(c=>c.id===id)||state.selectedCourse);return;} if(action==='delete-course'){if(!confirm('Delete this course? Lessons, enrollments, and quiz data will also be deleted.'))return;await run(async()=>{await api(`/api/courses/${encodeURIComponent(id)}`,{method:'DELETE'});state.selectedCourse=null;await refreshCourses();await refreshOverview();state.page='manage';render();showToast('Course deleted');},'Could not delete course: ');return;} if(action==='new-lesson'){openModal('lesson');return;} if(action==='edit-lesson'){openModal('lesson',state.selectedCourse?.lessons?.find(l=>l.id===id));return;} if(action==='delete-lesson'){if(!confirm('Delete this lesson?'))return;await run(async()=>{await api(`/api/lessons/${encodeURIComponent(id)}`,{method:'DELETE'});state.activeLesson=null;await refreshCourses();await reloadSelected();showToast('Lesson deleted');},'Could not delete lesson: ');return;} if(action==='edit-quiz'){openModal('quiz');return;} if(action==='student-detail'){const student=state.students.find(s=>s.id===id);if(student)openModal('student',student);return;} if(action==='close-modal'){closeModal();return;} if(action==='add-question'){state.quizDraft.push({text:'',options:['','','',''],correctIndex:0});render();return;} if(action==='remove-question'){state.quizDraft.splice(n(node.dataset.index),1);render();return;} if(action==='save-quiz'){const q=state.quizDraft; if(!q.length){showToast('Add at least one question',true);return;} if(q.some(x=>!x.text.trim()||x.options.some(v=>!v.trim()))){showToast('Complete every question and answer option',true);return;} await run(async()=>{await api(`/api/courses/${encodeURIComponent(state.selectedCourse.id)}/quiz`,{method:'PUT',body:JSON.stringify({questions:q.map(x=>({text:x.text.trim(),options:x.options.map(o=>o.trim()),correctIndex:n(x.correctIndex)}))})});state.modal=null;await loadTabData('quiz');await refreshCourses();await reloadSelected();showToast('Quiz saved');},'Could not save quiz: ');return;} if(action==='delete-post'){if(!confirm('Delete this discussion post?'))return;await run(async()=>{await api(`/api/courses/${encodeURIComponent(state.selectedCourse.id)}/discussions/${encodeURIComponent(id)}`,{method:'DELETE'});await loadTabData('discussion');render();showToast('Discussion deleted');},'Could not delete discussion: ');return;} });
document.addEventListener('input', event => { if(event.target.id==='course-search'){const pos=event.target.selectionStart;state.search=event.target.value;const currentPage=state.page;app.querySelector('.content').innerHTML=(currentPage==='mine'?catalog(true):catalog())+`<footer class="site-footer">Zhixing Learning · Learn without limits</footer>`;const input=$('#course-search');if(input){input.focus();input.setSelectionRange(pos,pos);}return;} const field=event.target.dataset.questionField; if(!field)return;const idx=n(event.target.dataset.index);const q=state.quizDraft[idx];if(!q)return;if(field==='text')q.text=event.target.value;else if(field==='option')q.options[n(event.target.dataset.option)]=event.target.value;else if(field==='correctIndex')q.correctIndex=n(event.target.value); });
document.addEventListener('change', event => { if(event.target.id==='auth-role-select'){state.authRole=event.target.value;state.authError='';render();return;} if(event.target.dataset.questionField==='correctIndex'){const q=state.quizDraft[n(event.target.dataset.index)];if(q)q.correctIndex=n(event.target.value);} });
document.addEventListener('submit', async event => { const form=event.target;if(!['auth-form','course-form','lesson-form','quiz-form','discussion-form','course-announcement-form'].includes(form.id))return;event.preventDefault();if(form.id==='auth-form'){const d=Object.fromEntries(new FormData(form));await run(async()=>{try{const payload=state.authMode==='register'?{...d,role:state.authRole,...(state.authRole==='student'?{studentId:d.accountId}:{})}:{identifier:d.identifier,password:d.password};const result=state.authMode==='register'?await api('/api/auth/register',{method:'POST',body:JSON.stringify(payload)}):await api('/api/auth/login',{method:'POST',body:JSON.stringify(payload)});state.user=result.user;state.authError='';if(state.user.role==='admin'){state.page='admin';}else{await refreshCourses();await refreshAnnouncements();if(state.user.role==='teacher')await refreshOverview();state.page='home';}render();showToast(state.authMode === 'register' && state.user.pendingSchool ? `Welcome, ${state.user.name}! School binding request sent for admin approval.` : `${state.authMode === 'register' ? 'Welcome' : 'Welcome back'}, ${state.user.name}!`);}catch(error){state.authError=error.message;render();}},'');return;} if(form.id==='course-form'){const d=Object.fromEntries(new FormData(form));const current=state.modal?.course;await run(async()=>{const path=current?.id?`/api/courses/${encodeURIComponent(current.id)}`:'/api/courses';const method=current?.id?'PATCH':'POST';const result=await api(path,{method,body:JSON.stringify(d)});state.modal=null;await refreshCourses();await refreshOverview();if(state.page==='detail' && current?.id)await reloadSelected();else render();showToast(current?.id?'Course updated':'Course created successfully');if(!current?.id && result.course?.id)await loadCourse(result.course.id);},'Could not save course: ');return;} if(form.id==='lesson-form'){const d=Object.fromEntries(new FormData(form));const current=state.modal?.lesson;await run(async()=>{await api(current?.id?`/api/lessons/${encodeURIComponent(current.id)}`:`/api/courses/${encodeURIComponent(state.selectedCourse.id)}/lessons`,{method:current?.id?'PATCH':'POST',body:JSON.stringify(d)});state.modal=null;await refreshCourses();await reloadSelected();showToast(current?.id?'Lesson updated':'Lesson added');},'Could not save lesson: ');return;} if(form.id==='quiz-form'){const questions=state.quiz?.questions||[];const answers=[];for(const q of questions){const selected=form.querySelector(`input[name="q-${CSS.escape(q.id)}"]:checked`);if(!selected){showToast('Answer every question before submitting',true);return;}answers.push({questionId:q.id,optionIndex:n(selected.value)});}await run(async()=>{const data=await api(`/api/courses/${encodeURIComponent(state.selectedCourse.id)}/quiz/submit`,{method:'POST',body:JSON.stringify({answers})});state.quizResult=data.attempt;await loadTabData('quiz');render();showToast('Quiz submitted. Your score has been recorded!');},'Could not submit: ');return;} if(form.id==='course-announcement-form'){const d=Object.fromEntries(new FormData(form));await run(async()=>{await api(`/api/courses/${encodeURIComponent(state.selectedCourse.id)}/announcements`,{method:'POST',body:JSON.stringify(d)});await refreshCourses();await reloadSelected();showToast('Course announcement published');},'Could not publish: ');return;} if(form.id==='discussion-form'){const content=new FormData(form).get('content')?.toString().trim();if(!content)return;await run(async()=>{await api(`/api/courses/${encodeURIComponent(state.selectedCourse.id)}/discussions`,{method:'POST',body:JSON.stringify({content})});await loadTabData('discussion');render();showToast('Discussion posted');},'Could not post: ');return;} });
document.addEventListener('keydown', event => { if(event.key==='Escape' && state.modal)closeModal(); });
async function init(){try{const data=await api('/api/auth/me');state.user=data.user||null;if(state.user){await refreshCourses();await refreshAnnouncements();if(state.user.role==='teacher')await refreshOverview();}render();}catch(error){app.innerHTML=`<div class="boot"><div class="boot-mark">!</div><h3>Unable to open your workspace</h3><p>${esc(error.message)}</p><button class="btn btn-primary" onclick="location.reload()">Retry</button></div>`;}}
function activityText(a) { const verbs = {course_created:'created a course',enrolled:'enrolled in a course',lesson_completed:'completed a lesson',quiz_submitted:'submitted a quiz',discussion:'posted a discussion'}; return [a.userName || 'Learner', verbs[a.kind] || 'participated in a course', a.kind === 'course_created' ? (a.detail || a.courseTitle) : (a.courseTitle || ''), a.kind === 'quiz_submitted' ? '(' + a.detail + ')' : ''].filter(Boolean).join(' '); }
init();
